const TYPE_ALLOWANCE = 3;
const NO_SPHINX_SCORE = 0;

/** Within the allowance the Sphinx scores 1, plus 1 for the company it keeps. */
const ALLOWANCE_SCORE = 2;

const POINTS_PER_TYPE_BEYOND_ALLOWANCE = 2;

/**
 * The Sphinx's own point is already earned inside the allowance, so the
 * beyond-allowance formula must not award it a second time.
 */
const SPHINX_POINT_ALREADY_COUNTED = 1;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

const countDistinctTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const scoreBeyondAllowance = (distinctTypeCount: number): number =>
  POINTS_PER_TYPE_BEYOND_ALLOWANCE * (distinctTypeCount - TYPE_ALLOWANCE) -
  SPHINX_POINT_ALREADY_COUNTED;

export const scoreArmy = (army: Card[]): number => {
  if (!army.some(isSphinx)) return NO_SPHINX_SCORE;

  const distinctTypeCount = countDistinctTypes(army);

  return distinctTypeCount > TYPE_ALLOWANCE
    ? scoreBeyondAllowance(distinctTypeCount)
    : ALLOWANCE_SCORE;
};

