const NO_SPHINX_SCORE = 0;

/** A Sphinx scores for itself, plus for each other type it keeps company with. */
const SPHINX_OWN_POINT = 1;

/** Up to this many types, the Sphinx's company is worth a flat single point. */
const TYPE_ALLOWANCE = 3;
const ALLOWANCE_COMPANY_POINTS = 1;

const POINTS_PER_TYPE_BEYOND_ALLOWANCE = 2;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

const countDistinctTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const scoreCompany = (distinctTypeCount: number): number =>
  distinctTypeCount > TYPE_ALLOWANCE
    ? POINTS_PER_TYPE_BEYOND_ALLOWANCE * (distinctTypeCount - TYPE_ALLOWANCE)
    : ALLOWANCE_COMPANY_POINTS;

export const scoreArmy = (army: Card[]): number =>
  army.some(isSphinx)
    ? SPHINX_OWN_POINT + scoreCompany(countDistinctTypes(army))
    : NO_SPHINX_SCORE;

